   if(trustFindError)throw trustFindError;
   if(trustRows?.length){const {error:trustUpdateError}=await supabase.from("dv_accounting_transaction_trust").update(trustPayload).eq("id",trustRows[0].id);if(trustUpdateError)throw new Error("RLS diagnostic: update on dv_accounting_transaction_trust failed. Details: "+trustUpdateError.message)}
   else{const {error:trustInsertError}=await supabase.from("dv_accounting_transaction_trust").insert([trustPayload]);if(trustInsertError)throw new Error("RLS diagnostic: insert into dv_accounting_transaction_trust failed. Details: "+trustInsertError.message)}
   const {error:postError}=await supabase.rpc("dv_accounting_post_trust_transaction",{p_company_id:resolvedCompanyId,p_bank_account_id:bank.id,p_transaction_id:transaction.id,p_ledger_date:depositForm.date,p_trust_account_type:"REAL_ESTATE_TRUST",p_direction:"DEPOSIT",p_client_name:depositForm.received_from.trim(),p_matter:transaction.transaction_number||transaction.property_address,p_description:"Deposit received for listing "+(transaction.transaction_number||transaction.id),p_amount:amount,p_reference:depositForm.reference_number.trim()||transaction.transaction_number||null});
   if(postError)throw new Error("The transaction and deposit details were saved, but posting to the Real Estate Trust ledger failed. Check Banking → Reconcile permission. Do not issue a receipt until resolved. Details: "+postError.message);
   const receipt={transaction_id:transaction.id,transaction_number:transaction.transaction_number||"—",property_address:[selected.property_address,selected.unit_number?"Unit "+selected.unit_number:"",selected.city,selected.province,selected.postal_code].filter(Boolean).join(", "),received_from:depositForm.received_from.trim(),date:depositForm.date,payment_type:depositForm.payment_type,reference_number:depositForm.reference_number.trim(),amount,bank_name:bank.name,receipt_number:"DR-"+String(transaction.transaction_number||transaction.id).replace(/[^A-Za-z0-9-]/g,"")};
   setDepositReceipt(receipt);setMessage("Deposit received, transaction linked, and deposit posted to Real Estate Trust. You can now issue the receipt.");
